def load() -> pd.DataFrame:
    import glob
    files = glob.glob('data/environment/input/water-body-testing-*.csv')
    dfs = [pd.read_csv(f) for f in files]
    return pd.concat(dfs, ignore_index=True)

def process(freshwater_exceedance):
    result = freshwater_exceedance[freshwater_exceedance['above_avg'] == True][['Year', 'exceedance_rate', 'avg_rate']].sort_values('Year')
    return result
